--
-- Table structure for table `revenue_share_records`
--

DROP TABLE IF EXISTS `revenue_share_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `revenue_share_records` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `revenue_collection_id` bigint unsigned NOT NULL,
  `shareholder_id` bigint unsigned NOT NULL,
  `revenue_type_id` bigint unsigned NOT NULL,
  `daily_payment_id` bigint unsigned DEFAULT NULL,
  `percentage` decimal(5,2) NOT NULL COMMENT 'Percentage share (0.00 to 100.00)',
  `fee_type` enum('percentage','fixed','hybrid') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'percentage',
  `fixed_amount` decimal(10,2) DEFAULT NULL COMMENT 'Fixed amount if fee_type is fixed or hybrid',
  `min_amount` decimal(10,2) DEFAULT NULL COMMENT 'Minimum amount constraint',
  `max_amount` decimal(10,2) DEFAULT NULL COMMENT 'Maximum amount constraint',
  `calculated_amount` decimal(10,2) NOT NULL COMMENT 'Amount calculated based on formula',
  `actual_amount` decimal(10,2) DEFAULT NULL COMMENT 'Actual amount paid (may differ from calculated)',
  `payment_status` enum('pending','paid','failed','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `paid_at` timestamp NULL DEFAULT NULL COMMENT 'When payment was made',
  `payment_reference` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'External payment reference',
  `payment_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Notes about the payment',
  `conditions` json DEFAULT NULL COMMENT 'Any special conditions that applied',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Additional notes about this share record',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `revenue_collection_shareholder_revenue_type_unique` (`revenue_collection_id`,`shareholder_id`,`revenue_type_id`),
  KEY `revenue_collection_shareholder_index` (`revenue_collection_id`,`shareholder_id`),
  KEY `shareholder_payment_status_index` (`shareholder_id`,`payment_status`),
  KEY `revenue_type_created_at_index` (`revenue_type_id`,`created_at`),
  KEY `payment_status_index` (`payment_status`),
  KEY `daily_payment_id_index` (`daily_payment_id`),
  CONSTRAINT `revenue_share_records_daily_payment_id_foreign` FOREIGN KEY (`daily_payment_id`) REFERENCES `revenue_shareholder_daily_payments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `revenue_share_records_revenue_collection_id_foreign` FOREIGN KEY (`revenue_collection_id`) REFERENCES `revenue_collections` (`id`) ON DELETE CASCADE,
  CONSTRAINT `revenue_share_records_revenue_type_id_foreign` FOREIGN KEY (`revenue_type_id`) REFERENCES `revenue_types` (`id`) ON DELETE CASCADE,
  CONSTRAINT `revenue_share_records_shareholder_id_foreign` FOREIGN KEY (`shareholder_id`) REFERENCES `shareholders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14561 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

