--
-- Table structure for table `revenue_shareholder_daily_payments`
--

DROP TABLE IF EXISTS `revenue_shareholder_daily_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `revenue_shareholder_daily_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `shareholder_id` bigint unsigned NOT NULL,
  `payment_date` date NOT NULL COMMENT 'Calendar date for this payment',
  `total_amount` decimal(12,2) NOT NULL COMMENT 'Total amount to be paid for this day',
  `payment_status` enum('pending','processing','completed','failed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `payment_reference` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'External payment reference',
  `monnify_reference` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Monnify transfer reference',
  `processed_at` timestamp NULL DEFAULT NULL COMMENT 'When payment was processed',
  `payment_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Notes about the payment',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shareholder_payment_date_unique` (`shareholder_id`,`payment_date`),
  KEY `shareholder_payment_date_index` (`shareholder_id`,`payment_date`),
  KEY `payment_date_status_index` (`payment_date`,`payment_status`),
  KEY `daily_payment_status_index` (`payment_status`),
  CONSTRAINT `revenue_shareholder_daily_payments_shareholder_id_foreign` FOREIGN KEY (`shareholder_id`) REFERENCES `shareholders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
